// Renames the PillComponent input `disableTooltip` -> `hideHint` in templates/CSS, tag-aware.
const fs = require("fs");
const path = require("path");

const root = process.argv[2];
const PILL_TAGS = ["app-pill", "app-fancy-pill", "app-status-pill"];
const OLD = "disableTooltip";
const NEW = "hideHint";

function walk(dir, out) {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, e.name);
        if (e.isDirectory()) walk(p, out);
        else if (/\.(ts|html|css|scss)$/.test(e.name)) out.push(p);
    }
    return out;
}

// Split tag text into quoted/unquoted segments; transform only unquoted parts.
function processTagText(tagText, refs) {
    let out = "";
    let i = 0;
    while (i < tagText.length) {
        const c = tagText[i];
        if (c === '"' || c === "'") {
            const end = tagText.indexOf(c, i + 1);
            const stop = end === -1 ? tagText.length : end + 1;
            out += tagText.slice(i, stop);
            i = stop;
        } else {
            let j = i;
            while (j < tagText.length && tagText[j] !== '"' && tagText[j] !== "'") j++;
            let seg = tagText.slice(i, j);
            for (const m of seg.matchAll(/#([A-Za-z_$][\w$]*)/g)) refs.add(m[1]);
            seg = seg.replace(/\[disableTooltip\]/g, "[" + NEW + "]");
            seg = seg.replace(/(?<![\w.\[$])disableTooltip(?![\w\]$])/g, NEW);
            out += seg;
            i = j;
        }
    }
    return out;
}

function processTemplateLike(src) {
    const refs = new Set();
    let out = "";
    let i = 0;
    const tagRe = /<(app-pill|app-fancy-pill|app-status-pill)(?=[\s/>])/g;
    let m;
    let last = 0;
    while ((m = tagRe.exec(src)) !== null) {
        const start = m.index;
        // scan to closing '>' honoring quotes
        let j = start + m[0].length;
        let q = null;
        while (j < src.length) {
            const ch = src[j];
            if (q) { if (ch === q) q = null; }
            else if (ch === '"' || ch === "'") q = ch;
            else if (ch === ">") break;
            j++;
        }
        const tagText = src.slice(start, j);
        out += src.slice(last, start) + processTagText(tagText, refs);
        last = j;
        tagRe.lastIndex = j;
    }
    out += src.slice(last);
    // template reference reads: ref.disableTooltip(
    for (const r of refs) {
        out = out.replace(new RegExp("\\b" + r.replace(/\$/g, "\\$") + "\\." + OLD + "\\(", "g"), r + "." + NEW + "(");
    }
    // CSS attribute selectors on pill tags
    out = out.replace(/(app-(?:fancy-|status-)?pill)\[disableTooltip\]/g, "$1[" + NEW + "]");
    return out;
}

let changed = 0;
for (const f of walk(root, [])) {
    const src = fs.readFileSync(f, "utf8");
    const out = processTemplateLike(src);
    if (out !== src) {
        fs.writeFileSync(f, out, "utf8");
        changed++;
    }
}
console.log("files changed:", changed);

